cd /src/php-src && apply_patch <<'PATCH'
*** Begin Patch
*** Update File: ext/spl/spl_observer.c
@@
 		element = spl_object_storage_attach(intern, Z_OBJ(entry), Z_ISUNDEF(inf)?NULL:&inf);
-		ZVAL_OBJ(&obj, element->obj);
-		var_replace(&var_hash, &entry, &obj);
+		/*
+		 * var_replace() stores the zval* into the unserialize reference table.
+		 * Using a stack zval here would make that table point into a returned
+		 * stack frame, causing stack-use-after-return during later reference
+		 * resolution (e.g. R:/r:).
+		 *
+		 * Allocate a temporary zval in var_hash-owned storage to ensure the
+		 * referenced zval remains valid for the duration of unserialization.
+		 */
+		{
+			zval *obj_tmp = var_tmp_var(&var_hash);
+			if (!obj_tmp) {
+				zval_ptr_dtor(&entry);
+				zval_ptr_dtor(&inf);
+				goto outexcept;
+			}
+			ZVAL_OBJ_COPY(obj_tmp, element->obj);
+			var_replace(&var_hash, &entry, obj_tmp);
+		}
 		var_replace(&var_hash, &inf, &element->inf);
 		zval_ptr_dtor(&entry);
 		ZVAL_UNDEF(&entry);
*** End Patch
PATCH

cd /src/php-src && python3 - <<'PY'
from pathlib import Path
path = Path('ext/spl/spl_observer.c')
s = path.read_text()
old = "		element = spl_object_storage_attach(intern, Z_OBJ(entry), Z_ISUNDEF(inf)?NULL:&inf);
		ZVAL_OBJ(&obj, element->obj);
		var_replace(&var_hash, &entry, &obj);
		var_replace(&var_hash, &inf, &element->inf);
"
new = "		element = spl_object_storage_attach(intern, Z_OBJ(entry), Z_ISUNDEF(inf)?NULL:&inf);
		/*
		 * var_replace() stores the zval* into the unserialize reference table.
		 * Using a stack zval here would make that table point into a returned
		 * stack frame, causing stack-use-after-return during later reference
		 * resolution (e.g. R:/r:).
		 *
		 * Allocate a temporary zval in var_hash-owned storage to ensure the
		 * referenced zval remains valid for the duration of unserialization.
		 */
		{
			zval *obj_tmp = var_tmp_var(&var_hash);
			if (!obj_tmp) {
				zval_ptr_dtor(&entry);
				zval_ptr_dtor(&inf);
				goto outexcept;
			}
			ZVAL_OBJ_COPY(obj_tmp, element->obj);
			var_replace(&var_hash, &entry, obj_tmp);
		}
		var_replace(&var_hash, &inf, &element->inf);
"
if old not in s:
    raise SystemExit('Target snippet not found; aborting')
path.write_text(s.replace(old, new))
print('patched', path)
PY

